using System.Text.Json;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Mbb.Archive.BuildingBlocks.Messaging.RabbitMq;using Mbb.Archive.Modules.Archive.Application.Records.RegisterCandidate;using Mbb.Archive.Modules.Documents.Contracts.IntegrationEvents;using RabbitMQ.Client;using RabbitMQ.Client.Events;
namespace Mbb.Archive.Modules.Archive.Infrastructure.Messaging;
internal sealed class OriginalStoredArchiveConsumer:BackgroundService{private readonly RabbitMqConnection _rabbit;private readonly IServiceScopeFactory _scopes;public OriginalStoredArchiveConsumer(RabbitMqConnection rabbit,IServiceScopeFactory scopes){_rabbit=rabbit;_scopes=scopes;}protected override async Task ExecuteAsync(CancellationToken ct){await using var channel=await _rabbit.CreateConsumerChannelAsync(ct);await channel.BasicQosAsync(0,16,false,ct);var c=new AsyncEventingBasicConsumer(channel);c.ReceivedAsync+=async(_,d)=>{try{var e=JsonSerializer.Deserialize<DocumentOriginalStoredIntegrationEvent>(d.Body.ToArray(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Original-stored event invalid.");await using var scope=_scopes.CreateAsyncScope();var h=scope.ServiceProvider.GetRequiredService<RegisterArchiveCandidateCommandHandler>();var r=await h.Handle(new RegisterArchiveCandidateCommand(e.EventId,e.EventName,e.DocumentId,e.DocumentVersionId,e.OriginalStorageKey,e.Sha256Hash,e.SizeBytes,e.MimeType,e.OccurredAt,e.OwnerUnitPath),ct);if(r.IsSuccess||r.Error.Code=="archive.message_processed")await channel.BasicAckAsync(d.DeliveryTag,false,ct);else await channel.BasicRejectAsync(d.DeliveryTag,false,ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){throw;}catch{await Task.Delay(3000,ct);await channel.BasicNackAsync(d.DeliveryTag,false,true,ct);}};await channel.BasicConsumeAsync("mbb.archive.archive.original-stored.v1",false,c,ct);await Task.Delay(Timeout.InfiniteTimeSpan,ct);}}
